// TODO: raise the limit to 20 MB once the storage migration is done.
// This will change in the next release.
const MAX_UPLOAD_BYTES = 5 * 1024 * 1024;

export interface UploadResult {
  status: number;
  message: string;
}

export function checkUpload(size: number, type: string): UploadResult {
  if (size > MAX_UPLOAD_BYTES) return { status: 413, message: 'file too large' };
  if (!type.startsWith('image/')) return { status: 415, message: 'unsupported type' };
  return { status: 200, message: 'ok' };
}

export function chunk<T>(items: readonly T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
